-- Aggregates only; no IDs, names, emails, messages, or secret values in output.
begin read only;
set local statement_timeout='30s';
with metrics as materialized (
 select u.id,sections.* from auth.users u cross join lateral (
 select 'account' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id',t.id,'email',to_jsonb(t)->'email','phone',to_jsonb(t)->'phone','created_at',to_jsonb(t)->'created_at','updated_at',to_jsonb(t)->'updated_at','email_confirmed_at',to_jsonb(t)->'email_confirmed_at','phone_confirmed_at',to_jsonb(t)->'phone_confirmed_at','is_admin',exists(select 1 from public.admin_users a where a.user_id=u.id)) value from auth.users t where t.id=u.id limit 100001) bounded
union all
select 'profile' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('pseudo',t.pseudo,'next_regular_pack_at',t.next_regular_pack_at,'next_decision_pack_at',t.next_decision_pack_at,'karas_balance',t.karas_balance,'avatar_url',case when t.avatar_url ~ '^https://[^/@?#]+/' then regexp_replace(t.avatar_url, '[?#].*$', '') else null end,'bio',t.bio,'featured_card_ids',t.featured_card_ids,'banner_card_id',t.banner_card_id,'is_public',t.is_public,'last_seen_at',t.last_seen_at,'presence_active',t.presence_active) value from public.user_profiles t where t.user_id=u.id limit 100001) bounded
union all
select 'progress' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('regular_packs_opened', t.regular_packs_opened, 'decision_packs_completed', t.decision_packs_completed, 'auctions_won', t.auctions_won, 'trades_completed', t.trades_completed, 'ssr_evolved_to_lr', t.ssr_evolved_to_lr) value from public.user_achievement_stats t where t.user_id=u.id limit 100001) bounded
union all
select 'collection' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'card_id', t.card_id, 'date_obtention', t.date_obtention, 'rarity', t.rarity, 'is_shiny', t.is_shiny, 'is_evolved', t.is_evolved, 'folder_id', t.folder_id, 'is_first_owner', t.is_first_owner, 'is_locked', t.is_locked) || jsonb_build_object('custom_image_url',case when t.custom_image_url ~ '^https://[^/@?#]+/' then regexp_replace(t.custom_image_url, '[?#].*$', '') else null end) value from public.user_cards t where t.user_id=u.id limit 100001) bounded
union all
select 'folders' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'nom', t.nom, 'created_at', t.created_at) value from public.folders t where t.user_id=u.id limit 100001) bounded
union all
select 'wishlist' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('card_id', t.card_id, 'created_at', t.created_at) value from public.wishlists t where t.user_id=u.id limit 100001) bounded
union all
select 'album_favorites' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('license', t.license, 'created_at', t.created_at) value from public.panini_album_favorites t where t.user_id=u.id limit 100001) bounded
union all
select 'decision_packs' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'status', t.status, 'created_at', t.created_at, 'claimed_at', t.claimed_at, 'kept_choice_id', t.kept_choice_id) value from public.decision_packs t where t.user_id=u.id limit 100001) bounded
union all
select 'achievements' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('achievement_id', t.achievement_id, 'completed_at', t.completed_at, 'claimed_at', t.claimed_at) value from public.user_achievements t where t.user_id=u.id limit 100001) bounded
union all
select 'watched_auctions' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('auction_id', t.auction_id) value from public.auction_watchers t where t.user_id=u.id limit 100001) bounded
union all
select 'messages' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'auction_id', t.auction_id, 'message', t.message, 'gif_url', t.gif_url, 'created_at', t.created_at) value from public.auction_chat_messages t where t.user_id=u.id limit 100001) bounded
union all
select 'decision_pack_choices' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'pack_id', t.pack_id, 'card_id', t.card_id, 'rarity', t.rarity, 'is_shiny', t.is_shiny, 'is_discarded', t.is_discarded, 'position', t.position) value from public.decision_pack_choices t join public.decision_packs p on p.id=t.pack_id where p.user_id=u.id limit 100001) bounded
union all
select 'bids' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'auction_id', t.auction_id, 'amount', t.amount, 'created_at', t.created_at) value from public.bids t where t.bidder_id=u.id limit 100001) bounded
union all
select 'auctions' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'starting_price', t.starting_price, 'duration_minutes', t.duration_minutes, 'ends_at', t.ends_at, 'status', t.status, 'created_at', t.created_at) || jsonb_build_object('role',case when t.seller_id=u.id then 'seller' when t.buyer_id=u.id then 'buyer' else 'bidder' end,'own_result_amount',case when t.status='sold' and u.id in(t.seller_id,t.buyer_id) then t.current_price else null end,'counterparty',jsonb_build_object('pseudo',(select p.pseudo from public.user_profiles p where p.user_id=case when t.seller_id=u.id then t.buyer_id else t.seller_id end),'date',t.created_at)) value from public.auctions t where t.seller_id=u.id or t.buyer_id=u.id or exists(select 1 from public.bids b where b.auction_id=t.id and b.bidder_id=u.id) limit 100001) bounded
union all
select 'trades' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'status', t.status, 'created_at', t.created_at, 'updated_at', t.updated_at) || jsonb_build_object('direction',case when t.from_user=u.id then 'sent' else 'received' end,'own_card_ids',case when t.from_user=u.id then t.offered_card_ids else t.requested_card_ids end,'own_karas',case when t.from_user=u.id then t.offered_karas else t.requested_karas end,'own_cards',coalesce((select jsonb_agg(jsonb_build_object('card_id',v->'id','name',v->'name','category',v->'category','rarity',v->'rarity','shiny',v->'shiny')) from jsonb_array_elements(case when jsonb_typeof(case when t.from_user=u.id then t.offered_cards_snapshot else t.requested_cards_snapshot end)='array' then case when t.from_user=u.id then t.offered_cards_snapshot else t.requested_cards_snapshot end else '[]'::jsonb end) v),'[]'::jsonb),'parent_offer_id',case when exists(select 1 from public.trade_offers parent where parent.id=t.parent_offer_id and (parent.from_user=u.id or parent.to_user=u.id)) then t.parent_offer_id else null end,'counterparty',jsonb_build_object('pseudo',(select p.pseudo from public.user_profiles p where p.user_id=case when t.from_user=u.id then t.to_user else t.from_user end),'date',t.created_at)) value from public.trade_offers t where t.from_user=u.id or t.to_user=u.id limit 100001) bounded
union all
select 'friendships' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'status', t.status, 'created_at', t.created_at, 'updated_at', t.updated_at) || jsonb_build_object('direction',case when t.user_id=u.id then 'sent' else 'received' end,'counterparty',jsonb_build_object('pseudo',(select p.pseudo from public.user_profiles p where p.user_id=case when t.user_id=u.id then t.friend_id else t.user_id end),'date',t.created_at)) value from public.friendships t where t.user_id=u.id or t.friend_id=u.id limit 100001) bounded
union all
select 'blocks' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('pseudo',(select p.pseudo from public.user_profiles p where p.user_id=t.blocked_id),'created_at',t.created_at) value from public.user_blocks t where t.blocker_id=u.id limit 100001) bounded
union all
select 'submitted_reports' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'reason', t.reason, 'context_type', t.context_type, 'created_at', t.created_at) value from public.user_reports t where t.reporter_id=u.id limit 100001) bounded
union all
select 'submitted_card_reports' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'card_id', t.card_id, 'reason', t.reason, 'created_at', t.created_at) value from public.card_reports t where t.reporter_id=u.id limit 100001) bounded
union all
select 'notifications' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id', t.id, 'type', t.type, 'read_at', t.read_at, 'created_at', t.created_at, 'achievement_id', t.achievement_id) || jsonb_build_object('reference_id',case when exists(select 1 from public.auctions a where a.id=t.reference_id and (a.seller_id=u.id or a.buyer_id=u.id or exists(select 1 from public.bids b where b.auction_id=a.id and b.bidder_id=u.id))) or exists(select 1 from public.trade_offers o where o.id=t.reference_id and (o.from_user=u.id or o.to_user=u.id)) or exists(select 1 from public.friendships f where f.id=t.reference_id and (f.user_id=u.id or f.friend_id=u.id)) then t.reference_id else null end,'actor',case when t.actor_user_id is not null and t.actor_user_id<>u.id then jsonb_build_object('pseudo',(select p.pseudo from public.user_profiles p where p.user_id=t.actor_user_id),'date',t.created_at) else null end) value from public.notifications t where t.user_id=u.id limit 100001) bounded
union all
select 'card_shares' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('card_id', t.card_id, 'card_name', t.card_name, 'franchise', t.franchise, 'rarity', t.rarity, 'shiny', t.shiny, 'show_pseudo', t.show_pseudo, 'display_pseudo', t.display_pseudo, 'created_at', t.created_at) || jsonb_build_object('catalogue_image_url',case when t.catalogue_image_url ~ '^https://[^/@?#]+/' then regexp_replace(t.catalogue_image_url, '[?#].*$', '') else null end) value from public.card_shares t where t.owner_id=u.id limit 100001) bounded
union all
select 'login_providers' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('provider', t.provider, 'created_at', t.created_at, 'updated_at', t.updated_at) value from auth.identities t where t.user_id=u.id limit 100001) bounded
union all
select 'avatar_files' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('type',case when jsonb_typeof(to_jsonb(t)->'metadata'->'mimetype')='string' then to_jsonb(t)->'metadata'->'mimetype' else null end,'size',case when (to_jsonb(t)->'metadata'->>'size') ~ '^[0-9]{1,15}$' then (to_jsonb(t)->'metadata'->>'size')::bigint else null end,'created_at',to_jsonb(t)->'created_at','updated_at',to_jsonb(t)->'updated_at','last_accessed_at',to_jsonb(t)->'last_accessed_at') value from storage.objects t where t.bucket_id='avatars' and (t.owner_id=u.id::text or to_jsonb(t)->>'owner'=u.id::text or split_part(t.name,'/',1)=u.id::text) limit 100001) bounded
union all
select 'catalogue_cards' section,count(*) n,coalesce(sum(octet_length(value::text)+2),0) bytes from (select jsonb_build_object('id',t.id,'name',t.nom,'category',t.categorie,'rarity',t.rarete_base,'franchises',coalesce((select jsonb_agg(f.franchise order by f.position) from public.card_franchises f where f.card_id=t.id),'[]'::jsonb)) value from public.cards t where exists(select 1 from public.user_cards c where c.user_id=u.id and c.card_id=t.id) or exists(select 1 from public.wishlists w where w.user_id=u.id and w.card_id=t.id) or exists(select 1 from public.decision_pack_choices c join public.decision_packs p on p.id=c.pack_id where p.user_id=u.id and c.card_id=t.id) or exists(select 1 from public.user_profiles p where p.user_id=u.id and p.banner_card_id=t.id) limit 100001) bounded
 ) sections
), totals as (select id,sum(n) n,sum(bytes)+8192 bytes from metrics group by id),
chosen as (select id from totals order by n desc,bytes desc limit 1)
select section,n,bytes from metrics where id=(select id from chosen)
union all select 'TOTAL',n,bytes from totals where id=(select id from chosen)
union all select 'MAX_BYTES_ANY_PLAYER',n,bytes from (select n,bytes from totals order by bytes desc limit 1) biggest
order by 1;
rollback;
